# DK AHT.  Aarhus - Hammel - Thorsø
#
let fa = path("d3.dk.ffh.1");
let ah = path("d3.dk.aht.1");
let ht = path("d3.dk.aht.2");

with detail = 3, railway = :first :pax :removed {
    with link = "point.dk.Aarhus-Hammelbanegården", railway = :station {
        marker(:bottom :de.bf, ah[:aah] >> 0.5md);
        slabel(:left :bold, ah[:aah] + (0dt, -1sh) + (3dt, -1.5dt),
            vbox(:right:base, "Aarhus", "Hammelbanegården")
        );
    }

    with link = "line.dk.AHT" {
        track(:lor,
                ah[:aah, :aah + 200m] >> 0.5md
            ..  fa[:aar.yr + 400m, :aar.yr] >> 0.5md >> 2ms >> 1.5mt
        );
        with layer = 1 track(:lor :casing,
                fa[:aar.yr + 0.1dl, :aar.yr] >> 0.5md >> 2ms >> 1.5mt
            ..  fa[:aar.yt + 0.1dl, :aar.yt] >> 0.5md >> 1ms >> 0.5mt
            ..  ah[:aar.xt + 1md, :aar.xt + 1.1md]
        );
        track(ah[:aar.xt + 1md, :vin - 0.49sw]);
    }

    with link = "point.dk.Viby-Nord", railway = :station {
        track(ah[:vin - 0.5sw, :vin + 0.5sw]);
        marker(:left :de.bf, ah[:vin] << 0.5mt);
        slabel(:ne, ah[:vin] << 0.5mt << 1sh + (2.5dt, 0.3dt), "Viby Nord");
    }

    with link = "line.dk.AHT" {
        track(ah[:vin + 0.49sw, :sta - 0.49sw]);
    }

    with link = "point.dk.Stavtrup", railway = :station {
        track(ah[:sta - 0.5sw, :sta + 0.5sw]);
        marker(:left :de.bf, ah[:sta] << 0.5mt);
        slabel(:ne, ah[:sta] << 0.5mt << 1sh + (2.5dt, 0.3dt),
            "Stavtrup"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:sta + 0.49sw, :con - 0.49sw]);
    }

    with link = "point.dk.Constantinsborg", railway = :station {
        track(ah[:con - 0.5sw, :con + 0.5sw]);
        marker(:right :de.hp, ah[:con] >> 0.5mt);
        slabel(:se, ah[:con] >> 0.5mt >> 1sh + (6.3dt, -0.3dt),
            "Constantinsborg"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:con + 0.49sw, :con + 0.81km]);
        line_label(:left:nw, ah[:con + 0.8km] << 0.5mt, "AHT");
        track(ah[:con + 0.79km, :orm - 0.49sw]);
    }

    with link = "point.dk.Ormslev", railway = :station {
        track(ah[:orm - 0.5sw, :orm + 0.5sw]);
        marker(:left :de.bf, ah[:orm] << 0.5mt);
