            "Ormslev"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:orm + 0.49sw, :ede - 0.49sw]);
    }

    with link = "point.dk.Edelhofvejen", railway = :station {
        track(ah[:ede - 0.5sw, :ede + 0.5sw]);
        marker(:right :de.hp, ah[:ede] >> 0.5mt);
        slabel(:top, ah[:ede] >> 0.5mt >> 1sh + (1.5dt, -0.3dt),
            "Edelhofvejen"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:ede + 0.49sw, :har - 0.49sw]);
    }

    with link = "point.dk.Harlev", railway = :station {
        track(ah[:har - 0.5sw, :har + 0.5sw]);
        marker(:left :de.bf, ah[:har] << 0.5mt);
        slabel(:bottom, ah[:har] << 0.5mt << 1sh + (1dt, 0.6dt),
