    with link = "point.dk.Silkeborgvej", railway = :station {
        track(ah[:sil - 0.5sw, :sil + 0.5sw]);
        marker(:right :de.hp, ah[:sil] >> 0.5mt);
        slabel(:left, ah[:sil] << 0.5mt + (-1dt, 1.5dt),
            "Silkeborgvej*"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:sil + 0.49sw, :hor - 0.49sw]);
    }

    with link = "point.dk.Hørslevbolevejen", railway = :station {
        track(ah[:hor - 0.5sw, :hor + 0.5sw]);
        marker(:right :de.hp, ah[:hor] >> 0.5mt);
        slabel(:right, ah[:hor] >> 0.5mt >> 1sh + (1dt, 1dt),
            "Hørslevbolevejen"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:hor + 0.49sw, :sko - 0.49sw]);
    }

    with link = "point.dk.Skovby", railway = :station {
        track(ah[:sko - 0.5sw, :sko + 0.5sw]);
        marker(:right :de.bf, ah[:sko] >> 0.5mt);
        slabel(:top, ah[:sko] >> 0.5mt >> 1sh + (0.8dt, -0.3dt),
            "Skovby"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:sko + 0.49sw, :sje - 0.49sw]);
    }

    with link = "point.dk.Sjellevejen", railway = :station {
        track(ah[:sje - 0.5sw, :sje + 0.5sw]);
        marker(:left :de.hp, ah[:sje] << 0.5mt);
        slabel(:left, ah[:sje] >> 0.5mt + (-1dt, -0.5dt),
            "Sjellevejen"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:sje + 0.49sw, :sme - 0.49sw]);
    }

    with link = "point.dk.Smedeskoven", railway = :station {
        track(ah[:sme - 0.5sw, :sme + 0.5sw]);
        marker(:left :de.hp, ah[:sme] << 0.5mt);
        slabel(:nw, ah[:sme] << 0.5mt << 1sh + (-3.5dt, 0.2dt),
            "Smedeskoven*"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:sme + 0.49sw, :gal - 0.49sw]);
    }

    with link = "point.dk.Galten", railway = :station {
        track(ah[:gal - 0.5sw, :gal + 0.5sw]);
        marker(:right :de.bf, ah[:gal] >> 0.5mt);
        slabel(:top, ah[:gal] >> 0.5mt >> 1sh + (-1dt, -0.3dt),
