    with link = "point.dk.Tovstrup-Mølle", railway = :station {
        track(ah[:tom - 0.5sw, :tom + 0.5sw]);
        marker(:right :de.hp, ah[:tom] >> 0.5mt);
        slabel(:right, ah[:tom] >> 0.5mt >> 1sh + (1.1dt, 1.0dt),
            "Tovstrup Mølle"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:tom + 0.49sw, :tov - 0.49sw]);
    }

    with link = "point.dk.Tovstrup", railway = :station {
        track(ah[:tov - 0.5sw, :tov + 0.5sw]);
        marker(:left :de.bf, ah[:tov] << 0.5mt);
        slabel(:bottom, ah[:tov] << 0.5mt << 1sh + (-2.5dt, 0.2dt),
            "Tovstrup"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:tov + 0.49sw, :rog - 0.49sw]);
    }

    with link = "point.dk.Røgen-Forsamlingshus", railway = :station {
        track(ah[:rog - 0.5sw, :rog + 0.5sw]);
        marker(:left :de.hp, ah[:rog] << 0.5mt);
        slabel(:left, ah[:rog] << 0.5mt << 1sh + (-1.3dt, 0.7dt),
            "Røgen Forsamlingshus"
        );
    }

    with link = "line.dk.AHT" {
        track(ah[:rog + 0.49sw, :spo - 0.49sw]);
