    with link = "point.dk.Sporup", railway = :station {
        track(ah[:spo - 0.5sw, :spo + 0.5sw]);
        marker(:right :de.bf, ah[:spo] >> 0.5mt);
        slabel(:right, ah[:spo] >> 0.5mt >> 1sh + (1.4dt, 1.2dt),
