    with link = "point.dk.Sporup-Farre-Vejen", railway = :station {
        track(ah[:far - 0.5sw, :far + 0.5sw]);
        marker(:left :de.hp, ah[:far] << 0.5mt);
        slabel(:left, ah[:far] << 0.5mt << 1sh + (-1.4dt, 0.8dt),
