    }

    with link = "line.dk.AHT" {
        track(ah[:far + 0.49sw, :far + 1.01km]);
        line_label(:right:w, ah[:far + 1km] >> 0.5mt, (0dt, 0.2dt), "AHT");
        track(ah[:far + 0.99km, :anb - 0.49sw]);
    }

    with link = "point.dk.Anbæk", railway = :station {
        track(ah[:anb - 0.5sw, :anb + 0.5sw]);
        marker(:left :de.hp, ah[:anb] << 0.5mt);
        marker(:left :de.exbf, ah[:anb] << 0.5mt);
        slabel(:left, ah[:anb] << 0.5mt << 1.4sh + (-1.4dt, 0.8dt),
