    with link = "point.dk.Hammel", railway = :station {
        track(ah[:ham.yt, :ham + 0.5sw] << 1ms << 1mt);
        track(ah[:ham.yt - 0.5seg, :ham + 0.5sw]);
        marker(:left :de.bf, ah[:ham] << 1ms << 1.5mt);
        slabel(:right :bold,
            ah[:ham + 0.5sw] << 1ms << 1.5mt + (0.8dt, -0.8dt),
            "Hammel"
        );
    }

    with link = "line.dk.AHT" {
        track(:lor,
                ht[:ham.yt - 0.1dl, :ham.yt] >> 1ms >> 1mt
            ..  ht[:ham.xt, :ham.xt + 0.1dl]
        );
        track(ht[:ham.xt, :tul - 0.49sw]);
    }

    with link = "point.dk.Tulstrup-Vejen", railway = :station {
        track(ht[:tul - 0.5sw, :tul + 0.5sw]);
        marker(:left :de.hp, ht[:tul] << 0.5mt);
        slabel(:left, ht[:tul] << 0.5mt << 1sh + (-1.4dt, 1dt),
            "Tulstrup Vejen"
        );
    }

    with link = "line.dk.AHT" {
