    with link = "point.dk.Vintersminde", railway = :station {
        track(ht[:vin - 0.5sw, :vin + 0.5sw]);
        marker(:right :de.hp, ht[:vin] >> 0.5mt);
        slabel(:right, ht[:vin] >> 0.5mt >> 1sh + (1.5dt, 0.4dt),
            "Vintersminde"
        );
