    with link = "line.dk.AHT" {
        track(ht[:vin + 0.49sw, :tho.xa - 4mt]);
        track(:ror,
                ht[:tho.xa - 4.1mt, :tho.xa - 4mt]
            ..  ht[:tho.ya, :tho.ya + 0.1dl] << 1ms << 1mt
